@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class AdministrativeStaff extends Employee {}

class Lecturer extends ResearchAssistant {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class Participation {
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "1" Employee : headed by dean
Institute "1" -- "1" Employee : total number of employees
ResearchAssistant "1..*" -- "1..*" Institute : assigned to
ResearchAssistant "1" -- "1..*" Participation
Participation "1..*" -- "1" Project
Lecturer "1..*" -- "1..*" Course : teaches

@enduml

